// Generated from quiet-orbit.html. Rebuild with: node build-html.js
export default "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover\"><style>html,body{margin:0;padding:0;background:#0b0e18}[hidden]{display:none!important}</style></head><body><title>Quiet Orbit</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700&family=Atkinson+Hyperlegible:wght@400;700&family=JetBrains+Mono:wght@400;500;600&display=swap\">\n<style>\n/* Layout: one-screen app. Phone = stats bar / tilted solar system / tabbed panel stacked; wide = system left, panel right.\n   Look: a dark-adapted observatory. Nothing on screen is brighter than a soft off-white; glows are faint and nothing flashes. */\n:root{\n  color-scheme: dark;\n  --void:#0b0e18; --deep:#10141f; --panel:#141927; --panel2:#191f30; --line:#262d44;\n  --fg:#c6cad6; --muted:#7f879d; --dim:#565e76;\n  --sun:#c4a36c; --teal:#73a39f; --rose:#b48693; --violet:#8f89bf;\n  --f-display:\"Sora\",\"Segoe UI\",system-ui,sans-serif;\n  --f-body:\"Atkinson Hyperlegible\",system-ui,-apple-system,sans-serif;\n  --f-mono:\"JetBrains Mono\",ui-monospace,Menlo,Consolas,monospace;\n  background:var(--void);\n}\n*{box-sizing:border-box}\n[hidden]{display:none !important}\nhtml,body{height:100%}\nbody{margin:0;background:var(--void);color:var(--fg);font-family:var(--f-body);font-size:14px;overflow:hidden;-webkit-tap-highlight-color:transparent;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;overscroll-behavior:none}\nbutton{font:inherit;color:inherit}\nbutton:focus-visible,input:focus-visible{outline:2px solid var(--teal);outline-offset:2px}\n.app{height:100%;display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(230px,44%) 1fr}\n@media (min-width:900px){\n  .app{grid-template-columns:minmax(0,1.2fr) minmax(380px,1fr);grid-template-rows:auto 1fr}\n  .stats{grid-column:1 / -1}\n  .scene{grid-row:2;grid-column:1}\n  .lab{grid-row:2;grid-column:2;border-left:1px solid var(--line);border-top:0 !important}\n}\n/* stats bar */\n.stats{display:flex;align-items:center;gap:14px;padding-block:10px;\n  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));\n  background:var(--deep);border-bottom:1px solid var(--line)}\n.brand{font-family:var(--f-display);font-weight:700;font-size:17px;letter-spacing:-.01em;margin-right:auto;display:flex;align-items:baseline;gap:8px;white-space:nowrap}\n.brand small{font-family:var(--f-mono);font-weight:400;font-size:11px;color:var(--muted)}\n.stat{display:flex;flex-direction:column;align-items:flex-end;min-width:0}\n.stat .k{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);white-space:nowrap}\n.stat .v{font-family:var(--f-mono);font-weight:500;font-size:14px;font-variant-numeric:tabular-nums;white-space:nowrap}\n.stat.cat .v{color:var(--teal)} .stat.seed .v{color:var(--sun)}\n.icon-btn{background:none;border:1px solid var(--line);border-radius:8px;padding:5px 9px;color:var(--muted);font-size:15px;line-height:1;cursor:pointer}\n/* scene */\n.scene{position:relative;min-height:0;overflow:hidden;background:var(--void)}\n.scene canvas{position:absolute;inset:0;width:100%;height:100%;display:block}\n#sky{pointer-events:none}\n#sys{touch-action:manipulation;cursor:pointer}\n.hud{position:absolute;left:max(14px,env(safe-area-inset-left,0px));top:12px;pointer-events:none;display:flex;flex-direction:column;gap:3px}\n.count{font-family:var(--f-display);font-weight:600;font-size:clamp(28px,5.5vw,46px);letter-spacing:-.02em;line-height:1;font-variant-numeric:tabular-nums}\n.count-sub{font-family:var(--f-mono);font-size:12px;color:var(--muted)}\n.starname{position:absolute;right:max(14px,env(safe-area-inset-right,0px));top:12px;text-align:right;pointer-events:none}\n.starname .n{font-family:var(--f-display);font-weight:600;font-size:14px;color:var(--sun)}\n.starname .c{font-family:var(--f-mono);font-size:11px;color:var(--muted)}\n.hint{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);font-family:var(--f-mono);font-size:12px;color:var(--muted);pointer-events:none;white-space:nowrap}\n.alert{position:absolute;left:max(12px,env(safe-area-inset-left,0px));bottom:12px;font-family:var(--f-mono);font-size:12px;padding:6px 12px;border-radius:999px;border:1px solid var(--line);background:rgba(16,20,31,.88);pointer-events:none;max-width:calc(100% - 24px);white-space:normal}\n.alert.sun{border-color:#5c4e36;color:var(--sun)}\n.alert.teal{border-color:#3a5552;color:var(--teal)}\n/* panel */\n.lab{display:flex;flex-direction:column;min-height:0;background:var(--panel);border-top:1px solid var(--line)}\n.tabs{display:flex;gap:4px;padding-block:8px;padding-left:max(12px,env(safe-area-inset-left,0px));padding-right:max(12px,env(safe-area-inset-right,0px));border-bottom:1px solid var(--line)}\n.tab{flex:1;min-width:0;background:none;border:1px solid transparent;border-radius:8px;padding:8px 4px;font-weight:700;font-size:13px;color:var(--muted);cursor:pointer;position:relative}\n.tab[aria-selected=\"true\"]{color:var(--fg);background:var(--panel2);border-color:var(--line)}\n.tab .dot{position:absolute;top:6px;right:8px;width:6px;height:6px;border-radius:50%;background:var(--teal)}\n.pane{flex:1;overflow-y:auto;padding-block:12px 24px;padding-left:max(12px,env(safe-area-inset-left,0px));padding-right:max(12px,env(safe-area-inset-right,0px));-webkit-overflow-scrolling:touch}\n.pane-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:0 2px 10px}\n.pane-head h2{margin:0;font-family:var(--f-display);font-size:15px;font-weight:600}\n.pane-head p{margin:2px 0 0;color:var(--muted);font-size:12px}\n.seg{display:flex;border:1px solid var(--line);border-radius:8px;overflow:hidden;flex-shrink:0}\n.seg button{background:none;border:0;padding:6px 10px;font-family:var(--f-mono);font-size:12px;color:var(--muted);cursor:pointer}\n.seg button[aria-pressed=\"true\"]{background:var(--panel2);color:var(--fg)}\n.list{display:flex;flex-direction:column;gap:8px}\n.row{display:grid;grid-template-columns:40px minmax(0,1fr) auto;gap:10px;align-items:center;padding:10px;border-radius:10px;background:var(--panel2);border:1px solid var(--line);cursor:pointer;text-align:left;width:100%}\n.row:disabled{cursor:not-allowed}\n.row:not(:disabled):hover{border-color:#36405e}\n.row.locked{opacity:.45}\n.ico{width:40px;height:40px;border-radius:9px;display:grid;place-items:center;background:var(--deep);border:1px solid var(--line)}\n.ico canvas{width:30px;height:30px}\n.meta{min-width:0}\n.meta .n{font-weight:700;display:flex;gap:6px;align-items:baseline;flex-wrap:wrap}\n.meta .n .lv{font-family:var(--f-mono);font-size:11px;color:var(--muted);font-weight:400}\n.meta .d{color:var(--muted);font-size:12px;margin-top:2px}\n.meta .bar{height:3px;border-radius:2px;background:var(--line);margin-top:6px;overflow:hidden}\n.meta .bar i{display:block;height:100%;background:var(--violet)}\n.price{font-family:var(--f-mono);font-size:13px;font-weight:500;text-align:right;white-space:nowrap}\n.price small{display:block;font-weight:400;color:var(--muted);font-size:11px}\n.row.can .price{color:var(--teal)}\n.row:not(.can) .price{color:var(--dim)}\n.row.flash{animation:flash .5s ease-out}\n@keyframes flash{0%{box-shadow:0 0 0 0 rgba(115,163,159,.35);border-color:var(--teal)}100%{box-shadow:0 0 0 8px rgba(115,163,159,0)}}\n.coach-hl{animation:coach 1.8s ease-in-out infinite;border-color:var(--teal)!important}\n@keyframes coach{50%{box-shadow:0 0 0 4px rgba(115,163,159,.18)}}\n.empty{color:var(--muted);font-size:13px;padding:6px 2px;line-height:1.5}\n/* catalog */\n.cat{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px}\n.entry{padding:10px;border-radius:10px;background:var(--panel2);border:1px solid var(--line);display:flex;flex-direction:column;gap:4px;text-align:left;cursor:pointer;min-width:0}\n.entry .t{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);display:flex;align-items:center;gap:6px}\n.entry .t i{width:8px;height:8px;border-radius:50%;display:inline-block}\n.entry .n{font-family:var(--f-display);font-weight:600;font-size:14px}\n.entry .how{font-size:12px;color:var(--dim)}\n.entry.unknown{cursor:default}\n.entry.unknown .n{color:var(--dim)}\n.entry.new{border-color:#3a5552}\n/* cards */\n.stack{display:flex;flex-direction:column;gap:12px}\n.card{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:12px}\n.card h3{margin:0;font-family:var(--f-display);font-size:18px;font-weight:600;text-wrap:balance}\n.card p{margin:0;color:var(--muted);line-height:1.55;max-width:62ch}\n.card .fact{color:var(--fg);font-size:15px}\n.kv{display:grid;grid-template-columns:1fr auto;gap:6px 12px;font-size:13px;margin:0}\n.kv dt{color:var(--muted)} .kv dd{margin:0;font-family:var(--f-mono);text-align:right;font-variant-numeric:tabular-nums}\n.big-btn{border:1px solid #5c4e36;background:rgba(196,163,108,.08);color:var(--sun);border-radius:10px;padding:12px 16px;font-weight:600;font-family:var(--f-display);font-size:15px;cursor:pointer}\n.big-btn:disabled{border-color:var(--line);color:var(--dim);background:none;cursor:not-allowed}\n.big-btn.confirm{background:#4a3f2c;color:#e0cfa8}\n.ghost{background:none;border:1px solid var(--line);border-radius:8px;padding:8px 12px;color:var(--muted);cursor:pointer;font-size:13px}\n.ghost.danger{border-color:#5e3c45;color:var(--rose)}\n.lineage{display:flex;gap:6px;flex-wrap:wrap}\n.lineage span{font-family:var(--f-mono);font-size:11px;padding:4px 8px;border-radius:999px;border:1px solid var(--line);color:var(--dim)}\n.lineage span.done{color:var(--fg);border-color:#3a4363}\n.lineage span.cur{color:var(--sun);border-color:#5c4e36}\n/* settings */\n.setrow{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:14px}\n.setrow small{display:block;color:var(--muted);font-size:12px;margin-top:2px}\n.toggle{width:46px;height:26px;border-radius:999px;border:1px solid var(--line);background:var(--deep);position:relative;cursor:pointer;flex-shrink:0}\n.toggle::after{content:\"\";position:absolute;top:3px;left:3px;width:18px;height:18px;border-radius:50%;background:var(--dim);transition:transform .15s,background .15s}\n.toggle[aria-pressed=\"true\"]{background:rgba(115,163,159,.15);border-color:#3a5552}\n.toggle[aria-pressed=\"true\"]::after{transform:translateX(20px);background:var(--teal)}\ninput[type=range]{width:160px;accent-color:var(--teal)}\n.rangeval{font-family:var(--f-mono);font-size:12px;color:var(--muted);min-width:38px;text-align:right}\n/* modal + toast */\n.modal{position:fixed;inset:0;background:rgba(5,7,12,.7);display:grid;place-items:center;z-index:20;padding:16px}\n.modal .card{max-width:400px;width:100%;max-height:calc(100% - 32px);overflow:auto}\n.modal .gain{font-family:var(--f-display);font-weight:600;font-size:28px;color:var(--sun)}\n.toast{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(16px + env(safe-area-inset-bottom,0px));background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:10px 14px;font-size:13px;z-index:30;max-width:calc(100% - 32px);display:flex;flex-direction:column;gap:2px}\n.toast b{font-family:var(--f-display);font-weight:600;color:var(--teal)}\n.toast span{color:var(--muted);font-size:12px}\n/* whole-screen dimmer driven by the Brightness setting */\n#dimmer{position:fixed;inset:0;background:#000;pointer-events:none;z-index:50;opacity:0}\n@media (prefers-reduced-motion:reduce){.row.flash,.coach-hl{animation:none}}\n@media (max-width:440px){\n  .stats{gap:10px}\n  .brand{font-size:15px} .brand small{display:none}\n  .stat .k{font-size:9px;letter-spacing:.08em} .stat .v{font-size:12.5px}\n  .tab{font-size:12px}\n}\n</style>\n\n<div class=\"app\" id=\"app\">\n  <header class=\"stats\">\n    <div class=\"brand\">Quiet Orbit <small id=\"sysShort\">SYSTEM 1</small></div>\n    <div class=\"stat\"><span class=\"k\">per sec</span><span class=\"v\" id=\"sRate\">0</span></div>\n    <div class=\"stat cat\"><span class=\"k\">found</span><span class=\"v\" id=\"sCat\">0</span></div>\n    <div class=\"stat seed\"><span class=\"k\">seeds</span><span class=\"v\" id=\"sSeed\">0</span></div>\n    <button class=\"icon-btn\" id=\"setBtn\" aria-label=\"Settings\">⚙</button>\n  </header>\n\n  <section class=\"scene\" id=\"scene\" aria-label=\"Your solar system. Tap the star to gather stardust.\">\n    <canvas id=\"sky\"></canvas>\n    <canvas id=\"sys\"></canvas>\n    <div class=\"hud\">\n      <div class=\"count\" id=\"count\">0</div>\n      <div class=\"count-sub\" id=\"countSub\">stardust</div>\n    </div>\n    <div class=\"starname\"><div class=\"n\" id=\"starKind\">Yellow dwarf</div><div class=\"c\" id=\"starAge\">System 1</div></div>\n    <div class=\"hint\" id=\"hint\">tap the star to gather stardust</div>\n    <div class=\"alert\" id=\"alert\" hidden></div>\n  </section>\n\n  <section class=\"lab\">\n    <div class=\"tabs\" role=\"tablist\">\n      <button class=\"tab\" role=\"tab\" id=\"tab-build\" aria-selected=\"true\" data-tab=\"build\">Build</button>\n      <button class=\"tab\" role=\"tab\" id=\"tab-res\" aria-selected=\"false\" data-tab=\"res\">Research<span class=\"dot\" id=\"resDot\" hidden></span></button>\n      <button class=\"tab\" role=\"tab\" id=\"tab-cat\" aria-selected=\"false\" data-tab=\"cat\">Catalog<span class=\"dot\" id=\"catDot\" hidden></span></button>\n      <button class=\"tab\" role=\"tab\" id=\"tab-nova\" aria-selected=\"false\" data-tab=\"nova\">Supernova<span class=\"dot\" id=\"novaDot\" hidden></span></button>\n    </div>\n\n    <div class=\"pane\" id=\"pane-build\">\n      <div class=\"pane-head\">\n        <div><h2>Build your system</h2><p>Every 25 of one kind doubles its output.</p></div>\n        <div class=\"seg\" id=\"buyMode\"><button data-m=\"1\" aria-pressed=\"true\">×1</button><button data-m=\"10\" aria-pressed=\"false\">×10</button><button data-m=\"max\" aria-pressed=\"false\">Max</button></div>\n      </div>\n      <div class=\"list\" id=\"prodList\"></div>\n    </div>\n\n    <div class=\"pane\" id=\"pane-res\" hidden>\n      <div class=\"pane-head\"><div><h2>Research</h2><p id=\"resSum\">One-time upgrades. They reset when your star goes supernova.</p></div></div>\n      <div class=\"list\" id=\"resList\"></div>\n    </div>\n\n    <div class=\"pane\" id=\"pane-cat\" hidden>\n      <div class=\"pane-head\"><div><h2>Sky catalog</h2><p id=\"catSum\">Each real object you find adds +3% to all stardust, forever.</p></div></div>\n      <div class=\"cat\" id=\"catList\"></div>\n    </div>\n\n    <div class=\"pane\" id=\"pane-nova\" hidden>\n      <div class=\"stack\">\n        <div class=\"card\">\n          <h3>Go supernova</h3>\n          <p>Your star collapses and its heavy elements seed a new system. Stardust, buildings and research reset. You keep your catalog and gain star seeds: each one adds +10% to all stardust, forever.</p>\n          <dl class=\"kv\">\n            <dt>Stardust this system</dt><dd id=\"nvRun\">0</dd>\n            <dt>Needed</dt><dd id=\"nvReq\">1.00B</dd>\n            <dt>Star seeds gained</dt><dd id=\"nvGain\" style=\"color:var(--sun)\">+0</dd>\n            <dt>Next star</dt><dd id=\"nvNext\">—</dd>\n          </dl>\n          <button class=\"big-btn\" id=\"novaBtn\" disabled>Go supernova</button>\n        </div>\n        <div class=\"card\">\n          <h3 style=\"font-size:15px\">Star history</h3>\n          <div class=\"lineage\" id=\"lineage\"></div>\n        </div>\n        <div class=\"card\">\n          <h3 style=\"font-size:15px\">Observer's notes</h3>\n          <p><b style=\"color:var(--fg)\">Tap planets</b> as they orbit. Each tap on a planet gathers three times the usual stardust.</p>\n          <p><b style=\"color:var(--fg)\">Meteors</b> drift across the sky now and then. Tap one for a bonus or a 20-second ×5 gravity surge.</p>\n          <p>While this page is closed your system keeps gathering at half speed for up to 8 hours.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n</div>\n\n<div class=\"modal\" id=\"modal\" hidden><div class=\"card\" id=\"modalCard\"></div></div>\n<div class=\"modal\" id=\"settings\" hidden>\n  <div class=\"card\" role=\"dialog\" aria-labelledby=\"setTitle\">\n    <h3 id=\"setTitle\">Settings</h3>\n    <div class=\"setrow\"><label for=\"bright\">Brightness<small>Dims the whole screen</small></label><span style=\"display:flex;align-items:center;gap:8px\"><input type=\"range\" id=\"bright\" min=\"40\" max=\"100\" step=\"5\" value=\"90\"><span class=\"rangeval\" id=\"brightVal\">90%</span></span></div>\n    <div class=\"setrow\"><span>Calm motion<small>Slower orbits, no twinkling</small></span><button class=\"toggle\" id=\"setCalm\" aria-pressed=\"false\" aria-label=\"Calm motion\"></button></div>\n    <div class=\"setrow\"><span>Sound<small>Soft tones on tap</small></span><button class=\"toggle\" id=\"setSound\" aria-pressed=\"true\" aria-label=\"Sound\"></button></div>\n    <dl class=\"kv\" id=\"statKv\"></dl>\n    <div style=\"display:flex;gap:8px;justify-content:space-between;flex-wrap:wrap\">\n      <button class=\"ghost danger\" id=\"wipeBtn\">Erase save</button>\n      <button class=\"big-btn\" id=\"setClose\" style=\"padding:8px 18px\">Done</button>\n    </div>\n  </div>\n</div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n<div id=\"dimmer\"></div>\n\n<script>\n(function(){\n\"use strict\";\n// ---------- data ----------\nconst PRODUCERS=[\n  {id:'dust', name:'Dust Cloud',   desc:'Cold grains drifting between stars',      base:15,    rate:0.2,   col:'#9a8f7e', up:'Accretion'},\n  {id:'rock', name:'Asteroid',     desc:'Rubble left over from planet building',  base:110,   rate:1.2,   col:'#8c8479', up:'Orbital resonance'},\n  {id:'comet',name:'Comet',        desc:'Dirty snowballs on long, looping orbits',base:1200,  rate:8,     col:'#86aab0', up:'Ice reserves'},\n  {id:'terra',name:'Rocky Planet', desc:'Iron cores under stone crusts',          base:13000, rate:47,    col:'#a87a62', up:'Plate tectonics'},\n  {id:'moon', name:'Moon',         desc:'Born from impacts or caught by gravity', base:1.4e5, rate:260,   col:'#a3a39c', up:'Tidal locking'},\n  {id:'giant',name:'Gas Giant',    desc:'Hydrogen worlds with storms for weather',base:2e6,   rate:1400,  col:'#b39a7c', up:'Deep storms'},\n  {id:'star', name:'Neighbor Star',desc:'Another sun, a few light-years away',    base:3e7,   rate:7800,  col:'#c7b48a', up:'Fusion shells'},\n  {id:'neb',  name:'Nebula',       desc:'Clouds of gas where stars are born',     base:4e8,   rate:44000, col:'#9a86b8', up:'Shock fronts'},\n  {id:'gal',  name:'Galaxy',       desc:'Hundreds of billions of stars',          base:6e9,   rate:2.6e5, col:'#8e9cc0', up:'Spiral arms'},\n  {id:'web',  name:'Supercluster', desc:'Galaxies strung along the cosmic web',   base:9e10,  rate:1.6e6, col:'#7fa6a0', up:'Cosmic web'},\n];\nconst PLANETS=[\n  {n:'Mercury',c:'#968f86',s:.15},{n:'Venus',c:'#bba57c',s:.22},{n:'Earth',c:'#5d84a3',s:.23,land:'#6f8a62'},{n:'Mars',c:'#a96d58',s:.18},\n  {n:'Jupiter',c:'#b39878',s:.48,bands:'#8f7259'},{n:'Saturn',c:'#bfae86',s:.42,ring:true},{n:'Uranus',c:'#8db0b2',s:.32},{n:'Neptune',c:'#6a82b0',s:.31}\n];\nconst STARS=[\n  {k:'Yellow dwarf', c:'#c4a36c'},{k:'Orange dwarf',c:'#c28a5f'},{k:'Red dwarf',c:'#b06d63'},\n  {k:'Blue-white star',c:'#8b9fbf'},{k:'Yellow giant',c:'#c2ad7a'},{k:'Blue supergiant',c:'#7d95bc'}\n];\nconst CATALOG=[\n  {id:'sun',  n:'The Sun',          t:'Star',     c:'#c4a36c', how:'Tap your star',          ok:()=>S.taps>=1,          f:'The Sun holds about 99.86% of all the mass in the solar system.'},\n  {id:'ceres',n:'Ceres',            t:'Dwarf planet',c:'#8c8479',how:'Own 1 asteroid',      ok:()=>own('rock')>=1,     f:'Ceres is the largest object in the asteroid belt, about 940 km across. It counts as a dwarf planet.'},\n  {id:'halley',n:\"Halley's Comet\",  t:'Comet',    c:'#86aab0', how:'Own 1 comet',            ok:()=>own('comet')>=1,    f:\"Halley's Comet comes back about every 76 years. It was last seen in 1986 and returns in 2061.\"},\n  {id:'merc', n:'Mercury',          t:'Planet',   c:'#968f86', how:'Own 1 rocky planet',     ok:()=>own('terra')>=1,    f:'A year on Mercury is 88 Earth days, but one sunrise to the next takes 176 Earth days.'},\n  {id:'venus',n:'Venus',            t:'Planet',   c:'#bba57c', how:'Own 2 rocky planets',    ok:()=>own('terra')>=2,    f:'Venus is the hottest planet, around 465 °C at the surface, even though Mercury is closer to the Sun.'},\n  {id:'earth',n:'Earth',            t:'Planet',   c:'#5d84a3', how:'Own 3 rocky planets',    ok:()=>own('terra')>=3,    f:'Earth is the only world we know of with oceans of liquid water on its surface.'},\n  {id:'mars', n:'Mars',             t:'Planet',   c:'#a96d58', how:'Own 4 rocky planets',    ok:()=>own('terra')>=4,    f:'Olympus Mons on Mars is about 22 km tall, roughly two and a half times the height of Everest.'},\n  {id:'luna', n:'The Moon',         t:'Moon',     c:'#a3a39c', how:'Own 1 moon',             ok:()=>own('moon')>=1,     f:'The Moon is drifting away from Earth by about 3.8 cm every year.'},\n  {id:'jup',  n:'Jupiter',          t:'Planet',   c:'#b39878', how:'Own 1 gas giant',        ok:()=>own('giant')>=1,    f:\"Jupiter's Great Red Spot is a storm wider than Earth that has been raging for well over 150 years.\"},\n  {id:'sat',  n:'Saturn',           t:'Planet',   c:'#bfae86', how:'Own 2 gas giants',       ok:()=>own('giant')>=2,    f:\"Saturn's main rings stretch about 280,000 km across, yet in most places they are only tens of meters thick.\"},\n  {id:'ura',  n:'Uranus',           t:'Planet',   c:'#8db0b2', how:'Own 3 gas giants',       ok:()=>own('giant')>=3,    f:'Uranus spins tipped on its side, with an axial tilt of about 98 degrees.'},\n  {id:'nep',  n:'Neptune',          t:'Planet',   c:'#6a82b0', how:'Own 4 gas giants',       ok:()=>own('giant')>=4,    f:'Neptune has the fastest winds measured in the solar system, over 2,000 km/h.'},\n  {id:'europa',n:'Europa',          t:'Moon',     c:'#b7ad98', how:'Own 10 moons',           ok:()=>own('moon')>=10,    f:\"Jupiter's moon Europa very likely hides a salty liquid ocean beneath its ice shell.\"},\n  {id:'titan',n:'Titan',            t:'Moon',     c:'#b39a6a', how:'Own 25 moons',           ok:()=>own('moon')>=25,    f:\"Saturn's moon Titan has lakes and seas made of liquid methane and ethane.\"},\n  {id:'pluto',n:'Pluto',            t:'Dwarf planet',c:'#a89584',how:'Own 50 asteroids',    ok:()=>own('rock')>=50,    f:'Pluto has a heart-shaped plain of nitrogen ice called Tombaugh Regio.'},\n  {id:'kuiper',n:'Kuiper Belt',     t:'Region',   c:'#7c97a3', how:'Own 25 comets',          ok:()=>own('comet')>=25,   f:'The Kuiper Belt is a wide ring of icy bodies beyond Neptune. Pluto lives there.'},\n  {id:'voy',  n:'Voyager 1',        t:'Probe',    c:'#9aa0ad', how:'Tap 1,000 times',        ok:()=>S.taps>=1000,       f:'Voyager 1, launched in 1977, is the most distant human-made object, more than 24 billion km from Earth.'},\n  {id:'prox', n:'Proxima Centauri', t:'Star',     c:'#b06d63', how:'Own 1 neighbor star',    ok:()=>own('star')>=1,     f:'Proxima Centauri is the closest star to the Sun, about 4.24 light-years away.'},\n  {id:'sirius',n:'Sirius',          t:'Star',     c:'#9fb0c8', how:'Own 10 neighbor stars',  ok:()=>own('star')>=10,    f:'Sirius is the brightest star in the night sky, about 8.6 light-years away.'},\n  {id:'betel',n:'Betelgeuse',       t:'Star',     c:'#b4705c', how:'Own 25 neighbor stars',  ok:()=>own('star')>=25,    f:'Betelgeuse is a red supergiant. Put in place of the Sun, it would reach past the orbit of Mars.'},\n  {id:'orion',n:'Orion Nebula',     t:'Nebula',   c:'#9a86b8', how:'Own 1 nebula',           ok:()=>own('neb')>=1,      f:'The Orion Nebula is a star nursery about 1,340 light-years away. You can see it without a telescope.'},\n  {id:'crab', n:'Crab Nebula',      t:'Nebula',   c:'#a58a96', how:'Own 10 nebulae',         ok:()=>own('neb')>=10,     f:'The Crab Nebula is what remains of a supernova that astronomers saw in the year 1054.'},\n  {id:'pillar',n:'Pillars of Creation',t:'Nebula',c:'#8f9f86', how:'Own 25 nebulae',         ok:()=>own('neb')>=25,     f:'The Pillars of Creation in the Eagle Nebula are columns of gas and dust several light-years tall.'},\n  {id:'milky',n:'Milky Way',        t:'Galaxy',   c:'#8e9cc0', how:'Own 1 galaxy',           ok:()=>own('gal')>=1,      f:'Our galaxy, the Milky Way, holds somewhere between 100 and 400 billion stars.'},\n  {id:'andro',n:'Andromeda',        t:'Galaxy',   c:'#9a93b8', how:'Own 10 galaxies',        ok:()=>own('gal')>=10,     f:'The Andromeda Galaxy is about 2.5 million light-years away and is slowly heading toward the Milky Way.'},\n  {id:'sgra', n:'Sagittarius A*',   t:'Black hole',c:'#7a7f93',how:'Own 25 galaxies',        ok:()=>own('gal')>=25,     f:'A black hole about 4 million times the mass of the Sun sits at the center of the Milky Way.'},\n  {id:'lani', n:'Laniakea',         t:'Supercluster',c:'#7fa6a0',how:'Own 1 supercluster',  ok:()=>own('web')>=1,      f:'Laniakea is the supercluster that contains the Milky Way. It spans about 520 million light-years.'},\n  {id:'cmb',  n:'Cosmic background',t:'Light',    c:'#a0907a', how:'1 quadrillion lifetime stardust',ok:()=>S.life>=1e15, f:'The cosmic microwave background is the oldest light we can see, released about 380,000 years after the Big Bang.'},\n];\nconst SCOPES=['Brass spyglass','Refractor lens','Reflector mirror','Adaptive optics','Radio dish array','Space telescope','Interferometer'];\nconst NUM=['I','II','III','IV','V'];\nconst RESEARCH=[];\nSCOPES.forEach((n,i)=>RESEARCH.push({id:'tap'+i,n,d:'Tap yield ×2',cost:100*Math.pow(18,i),req:()=>S.taps>=10*(i+1)||S.life>=100*Math.pow(18,i)*0.5,kind:'tap'}));\nfor(let i=0;i<5;i++) RESEARCH.push({id:'track'+i,n:'Sidereal drive '+NUM[i],d:'Each tap also gathers 1% of your per-second rate',cost:4000*Math.pow(40,i),req:()=>S.life>=2000*Math.pow(40,i),kind:'track'});\nfor(let i=0;i<4;i++) RESEARCH.push({id:'grav'+i,n:'Gravity assist '+NUM[i],d:'+50% all stardust',cost:1e5*Math.pow(120,i),req:()=>S.life>=5e4*Math.pow(120,i),kind:'grav'});\nconst TIERS=[10,25,50,100,150], TMULT=[10,60,600,8000,1.2e5];\nPRODUCERS.forEach(p=>TIERS.forEach((t,i)=>RESEARCH.push({id:p.id+i,n:p.up+' '+NUM[i],d:p.name+' output ×2',cost:p.base*TMULT[i],req:()=>own(p.id)>=t,kind:'prod',p:p.id,need:t})));\nconst NOVA_REQ=1e9, KEY='quiet-orbit-v1', OFFLINE_CAP=8*3600;\n\n// ---------- state ----------\nfunction fresh(){return {sd:0,run:0,life:0,taps:0,owned:{},res:[],cat:[],seen:[],seeds:0,novas:0,buy:'1',sound:true,bright:90,calm:false,\n  last:Date.now(),started:Date.now(),best:0,boostUntil:0,catches:0};}\nlet S=fresh();\nconst reducedPref=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;\nfunction load(d){\n  if(!d){ try{ const raw=localStorage.getItem(KEY); if(raw) d=JSON.parse(raw);}catch(e){} }\n  if(d) S=Object.assign(fresh(),d); else if(reducedPref) S.calm=true;\n}\nfunction save(){ S.last=Date.now(); try{ localStorage.setItem(KEY,JSON.stringify(S)); }catch(e){} }\nconst hot=window.claude&&window.claude.hot;\nif(hot&&hot.snapshot){ try{ hot.snapshot(()=>({S})); }catch(e){} }\n\n// ---------- math ----------\nconst own=id=>S.owned[id]||0;\nconst has=id=>S.res.includes(id);\nconst countRes=k=>S.res.filter(id=>{const r=RESEARCH.find(x=>x.id===id);return r&&r.kind===k;}).length;\nfunction boostMult(){ return Date.now()<S.boostUntil?5:1; }\nfunction globalMult(){ return (1+0.1*S.seeds)*(1+0.03*S.cat.length)*Math.pow(1.5,countRes('grav'))*boostMult(); }\nfunction prodMult(p){ let m=Math.pow(2,Math.floor(own(p.id)/25)); for(let i=0;i<5;i++) if(has(p.id+i)) m*=2; return m; }\nfunction prodOut(p){ return p.rate*own(p.id)*prodMult(p); }\nfunction rate(){ let s=0; for(const p of PRODUCERS) s+=prodOut(p); return s*globalMult(); }\nfunction unitCost(p,o){ return p.base*Math.pow(1.15,o); }\nfunction costN(p,n){ return unitCost(p,own(p.id))*(Math.pow(1.15,n)-1)/0.15; }\nfunction maxN(p){ const c0=unitCost(p,own(p.id)); if(S.sd<c0) return 0; return Math.floor(Math.log(S.sd*0.15/c0+1)/Math.log(1.15)); }\nfunction buyCount(p){ return S.buy==='max'?Math.max(1,maxN(p)):+S.buy; }\nfunction tapValue(){ return Math.pow(2,countRes('tap'))*(1+0.1*S.seeds)*(1+0.03*S.cat.length)*boostMult()+rate()*0.01*countRes('track'); }\nfunction novaGain(){ return S.run<NOVA_REQ?0:Math.floor(Math.sqrt(S.run/1e8)); }\nconst star=i=>STARS[i%STARS.length];\nfunction earn(n){ S.sd+=n; S.run+=n; S.life+=n; }\n\n// ---------- format ----------\nconst SUF=['','K','M','B','T','Qa','Qi','Sx','Sp','Oc','No','Dc'];\nfunction fmt(n){\n  if(!isFinite(n)) return '∞';\n  if(n<1000) return n<10&&n%1?(Math.floor(n*10)/10).toFixed(1):Math.floor(n).toString();\n  const e=Math.floor(Math.log10(n)/3);\n  if(e<SUF.length){ const x=n/Math.pow(1000,e); return (x<10?x.toFixed(2):x<100?x.toFixed(1):Math.floor(x))+SUF[e]; }\n  return n.toExponential(2).replace('+','');\n}\nfunction fmtTime(s){ s=Math.floor(s); const h=Math.floor(s/3600),m=Math.floor(s%3600/60); return h?`${h}h ${m}m`:m?`${m}m ${s%60}s`:`${s}s`; }\n\n// ---------- colour helpers ----------\nfunction rgb(h){ return [parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)]; }\nfunction mix(h,t,k){ const a=rgb(h),b=rgb(t); return `rgb(${a.map((v,i)=>Math.round(v+(b[i]-v)*k)).join(',')})`; }\nfunction rgba(h,a){ const c=rgb(h); return `rgba(${c[0]},${c[1]},${c[2]},${a})`; }\n\n// ---------- icons ----------\nfunction drawIcon(x,kind,col){\n  x.save(); x.translate(30,30); x.lineWidth=2.4; x.strokeStyle=col; x.fillStyle=rgba(col,.3);\n  const circ=(r,fill)=>{x.beginPath();x.arc(0,0,r,0,7);if(fill){x.fillStyle=fill;x.fill();}};\n  switch(kind){\n    case 'dust': for(let i=0;i<14;i++){const a=i*2.4,r=4+i*1.3;x.fillStyle=rgba(col,.35+.4*(i%3)/2);x.beginPath();x.arc(Math.cos(a)*r,Math.sin(a)*r,1.8,0,7);x.fill();} break;\n    case 'rock': x.beginPath(); [16,12,17,13,15,11,16,14].forEach((r,i)=>{const a=i/8*6.283;x.lineTo(Math.cos(a)*r,Math.sin(a)*r);}); x.closePath(); x.fill(); x.stroke(); break;\n    case 'comet': { const g=x.createLinearGradient(8,-8,-22,22); g.addColorStop(0,rgba(col,.7)); g.addColorStop(1,rgba(col,0)); x.strokeStyle=g; x.lineWidth=8; x.lineCap='round'; x.beginPath(); x.moveTo(8,-8); x.lineTo(-20,20); x.stroke(); circ(6,col); } break;\n    case 'terra': { const g=x.createRadialGradient(-6,-6,2,0,0,17); g.addColorStop(0,mix(col,'#e8e0d0',.25)); g.addColorStop(1,mix(col,'#000000',.55)); circ(16,g); } break;\n    case 'moon': circ(15,col); x.globalCompositeOperation='destination-out'; x.beginPath(); x.arc(8,-5,13,0,7); x.fill(); break;\n    case 'giant': { circ(14,col); x.strokeStyle=mix(col,'#000000',.35); x.lineWidth=2; [-6,0,6].forEach(y=>{x.beginPath();x.moveTo(-13,y);x.lineTo(13,y);x.stroke();}); x.strokeStyle=rgba(col,.8); x.lineWidth=2; x.beginPath(); x.ellipse(0,0,25,7,-.35,0,7); x.stroke(); } break;\n    case 'star': x.beginPath(); for(let i=0;i<8;i++){const r=i%2?5:18,a=i/8*6.283-1.571;x.lineTo(Math.cos(a)*r,Math.sin(a)*r);} x.closePath(); x.fillStyle=rgba(col,.75); x.fill(); break;\n    case 'neb': [[-6,-3,13,.35],[7,4,12,.3],[0,8,9,.25],[3,-8,8,.25]].forEach(([a,b,r,o])=>{const g=x.createRadialGradient(a,b,0,a,b,r);g.addColorStop(0,rgba(col,o+.25));g.addColorStop(1,rgba(col,0));x.fillStyle=g;x.beginPath();x.arc(a,b,r,0,7);x.fill();}); break;\n    case 'gal': x.lineWidth=2.2; for(let arm=0;arm<2;arm++){x.beginPath();for(let t=0;t<3.6;t+=.12){const r=2+t*5,a=t+arm*3.1416;x.lineTo(Math.cos(a)*r,Math.sin(a)*r*.6);}x.stroke();} circ(3.5,col); break;\n    case 'web': { const pts=[[-15,-10],[-2,-15],[13,-6],[-11,8],[4,4],[14,13],[-3,16]]; x.strokeStyle=rgba(col,.5); x.lineWidth=1.4; [[0,1],[1,2],[0,3],[1,4],[3,4],[4,5],[2,5],[3,6],[4,6]].forEach(([a,b])=>{x.beginPath();x.moveTo(...pts[a]);x.lineTo(...pts[b]);x.stroke();}); x.fillStyle=col; pts.forEach(p=>{x.beginPath();x.arc(p[0],p[1],2.4,0,7);x.fill();}); } break;\n    case 'tap': x.strokeStyle=col; x.lineWidth=3; x.beginPath(); x.moveTo(-14,8); x.lineTo(10,-8); x.stroke(); x.beginPath(); x.arc(12,-9,5,0,7); x.stroke(); x.beginPath(); x.moveTo(-4,2); x.lineTo(-10,16); x.moveTo(-4,2); x.lineTo(2,16); x.stroke(); break;\n    case 'track': x.beginPath(); x.arc(0,0,14,0,7); x.stroke(); x.beginPath(); x.moveTo(0,0); x.lineTo(0,-10); x.moveTo(0,0); x.lineTo(8,4); x.stroke(); break;\n    case 'grav': x.beginPath(); x.ellipse(0,0,18,8,0,0,7); x.stroke(); x.beginPath(); x.ellipse(0,0,10,4,0,0,7); x.stroke(); circ(4,col); break;\n  }\n  x.restore();\n}\nfunction iconCanvas(kind,col){ const c=document.createElement('canvas'); c.width=c.height=60; drawIcon(c.getContext('2d'),kind,col); return c; }\n\n// ---------- DOM ----------\nconst $=id=>document.getElementById(id);\nconst prodRows={};\nfunction buildProducers(){\n  const list=$('prodList'); list.innerHTML='';\n  PRODUCERS.forEach(p=>{\n    const b=document.createElement('button'); b.className='row'; b.id='prod-'+p.id;\n    const ico=document.createElement('div'); ico.className='ico'; ico.appendChild(iconCanvas(p.id==='terra'||p.id==='giant'||p.id==='moon'?p.id:p.id,p.col));\n    const meta=document.createElement('div'); meta.className='meta';\n    meta.innerHTML='<div class=\"n\"><span></span><span class=\"lv\"></span></div><div class=\"d\"></div><div class=\"bar\"><i></i></div>';\n    const price=document.createElement('div'); price.className='price';\n    b.append(ico,meta,price); list.appendChild(b);\n    b.addEventListener('click',()=>buyProducer(p));\n    prodRows[p.id]={b,name:meta.querySelector('.n span'),lv:meta.querySelector('.lv'),d:meta.querySelector('.d'),bar:meta.querySelector('.bar i'),price};\n  });\n}\nfunction renderProducers(){\n  const gm=globalMult(); let hiddenShown=false;\n  PRODUCERS.forEach((p,i)=>{\n    const r=prodRows[p.id], o=own(p.id);\n    const visible=i===0||own(PRODUCERS[i-1].id)>0||S.run>=p.base*0.5||o>0;\n    if(!visible){ if(hiddenShown){ r.b.hidden=true; return; } hiddenShown=true; }\n    r.b.hidden=false;\n    const n=buyCount(p), c=costN(p,n), can=visible&&S.sd>=c;\n    r.b.disabled=!can; r.b.classList.toggle('can',can); r.b.classList.toggle('locked',!visible);\n    r.name.textContent=visible?p.name:'Unknown object';\n    r.lv.textContent=o?'×'+o:'';\n    const each=p.rate*prodMult(p)*gm;\n    r.d.textContent=visible?(o?`${fmt(prodOut(p)*gm)}/s total · ${p.desc}`:`${fmt(each)}/s each · ${p.desc}`):'Keep gathering to spot it';\n    r.bar.style.width=((o%25)/25*100)+'%';\n    r.price.innerHTML=visible?`${fmt(c)}<small>×${n}</small>`:'?<small>&nbsp;</small>';\n  });\n}\nlet resSig='';\nfunction availableResearch(){ return RESEARCH.filter(r=>!has(r.id)&&r.req()).sort((a,b)=>a.cost-b.cost); }\nfunction renderResearch(){\n  const av=availableResearch();\n  $('resDot').hidden=!av.some(r=>S.sd>=r.cost);\n  if(tab!=='res') return;\n  const sig=av.map(r=>r.id+(S.sd>=r.cost?1:0)).join(',');\n  if(sig===resSig) return; resSig=sig;\n  const list=$('resList'); list.innerHTML='';\n  $('resSum').textContent=`${S.res.length} of ${RESEARCH.length} done. One-time upgrades; they reset on supernova.`;\n  if(!av.length){ list.innerHTML='<div class=\"empty\">Nothing to research right now. Build more and new projects will appear here.</div>'; return; }\n  av.slice(0,14).forEach(r=>{\n    const can=S.sd>=r.cost, b=document.createElement('button'); b.className='row'+(can?' can':''); b.disabled=!can;\n    const p=r.p&&PRODUCERS.find(x=>x.id===r.p);\n    const ico=document.createElement('div'); ico.className='ico'; ico.appendChild(iconCanvas(p?p.id:r.kind,p?p.col:(r.kind==='tap'?'#c4a36c':r.kind==='track'?'#73a39f':'#8f89bf')));\n    const meta=document.createElement('div'); meta.className='meta'; meta.innerHTML=`<div class=\"n\"><span>${r.n}</span></div><div class=\"d\">${r.d}</div>`;\n    const price=document.createElement('div'); price.className='price'; price.innerHTML=`${fmt(r.cost)}<small>stardust</small>`;\n    b.append(ico,meta,price); b.addEventListener('click',()=>buyResearch(r)); list.appendChild(b);\n  });\n}\nlet catSig='';\nfunction renderCatalog(){\n  $('catDot').hidden=!S.cat.some(id=>!S.seen.includes(id));\n  if(tab!=='cat') return;\n  const sig=S.cat.join(',')+'|'+S.seen.length; if(sig===catSig) return; catSig=sig;\n  $('catSum').textContent=`${S.cat.length} of ${CATALOG.length} found · +${S.cat.length*3}% to all stardust. Tap an entry to read about it.`;\n  $('catList').innerHTML=CATALOG.map(c=>{\n    const got=S.cat.includes(c.id), nw=got&&!S.seen.includes(c.id);\n    return `<button class=\"entry${got?'':' unknown'}${nw?' new':''}\" data-id=\"${c.id}\" ${got?'':'disabled'}>\n      <span class=\"t\"><i style=\"background:${got?c.c:'#262d44'}\"></i>${got?c.t:'Unknown'}${nw?' · new':''}</span>\n      <span class=\"n\">${got?c.n:'???'}</span>${got?'':`<span class=\"how\">${c.how}</span>`}</button>`;\n  }).join('');\n}\n$('catList').addEventListener('click',e=>{\n  const b=e.target.closest('.entry'); if(!b||b.disabled) return; const c=CATALOG.find(x=>x.id===b.dataset.id);\n  if(!S.seen.includes(c.id)) S.seen.push(c.id);\n  showModal(`<span class=\"t\" style=\"font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted)\">${c.t}</span><h3>${c.n}</h3><p class=\"fact\">${c.f}</p><button class=\"big-btn\" id=\"mOk\">Close</button>`);\n  renderCatalog();\n});\nfunction renderNova(){\n  const g=novaGain();\n  $('nvRun').textContent=fmt(S.run); $('nvReq').textContent=fmt(NOVA_REQ); $('nvGain').textContent='+'+g; $('nvNext').textContent=star(S.novas+1).k;\n  const b=$('novaBtn');\n  if(!b.classList.contains('confirm')){ b.disabled=g<=0; b.textContent=g>0?`Go supernova (+${g} star seeds)`:`Gather ${fmt(NOVA_REQ)} stardust to go supernova`; }\n  $('novaDot').hidden=g<=0;\n  let h=''; for(let i=0;i<=S.novas+1;i++){ h+=`<span class=\"${i<S.novas?'done':i===S.novas?'cur':''}\">${i+1}. ${i<=S.novas+1?star(i).k:'?'}</span>`; }\n  $('lineage').innerHTML=h;\n}\nconst el={count:$('count'),countSub:$('countSub'),rate:$('sRate'),cat:$('sCat'),seed:$('sSeed'),alert:$('alert'),hint:$('hint')};\nfunction renderTop(){\n  const r=rate();\n  el.count.textContent=fmt(S.sd);\n  el.countSub.textContent=`stardust · ${fmt(tapValue())} per tap`;\n  el.rate.textContent=fmt(r); el.cat.textContent=`${S.cat.length}/${CATALOG.length}`; el.seed.textContent=S.seeds;\n  $('starKind').textContent=star(S.novas).k; $('starAge').textContent='System '+(S.novas+1); $('sysShort').textContent='SYSTEM '+(S.novas+1);\n  if(Date.now()<S.boostUntil){ el.alert.hidden=false; el.alert.className='alert sun'; el.alert.textContent=`Gravity surge ×5 · ${Math.ceil((S.boostUntil-Date.now())/1000)}s`; }\n  else if(meteor){ el.alert.hidden=false; el.alert.className='alert teal'; el.alert.textContent='A meteor is passing. Tap it.'; }\n  else { const c=coachText(); if(c){ el.alert.hidden=false; el.alert.className='alert teal'; el.alert.textContent=c; } else el.alert.hidden=true; }\n  el.hint.hidden=S.taps>=5||!el.alert.hidden;\n  const first=S.novas===0&&S.taps>=5&&!Object.keys(S.owned).length&&S.sd>=unitCost(PRODUCERS[0],0);\n  $('prod-dust').classList.toggle('coach-hl',first);\n}\nfunction coachText(){\n  if(S.novas>0||S.taps<5) return '';\n  if(!Object.keys(S.owned).length) return S.sd>=15?'Build a Dust Cloud below. It gathers stardust for you.':'Keep tapping the star. Your first Dust Cloud costs 15.';\n  if(!S.res.length&&availableResearch().some(r=>S.sd>=r.cost)) return 'Research is ready. Open the Research tab.';\n  return '';\n}\nfunction renderAll(){ renderTop(); if(tab==='build') renderProducers(); renderResearch(); renderCatalog(); if(tab==='nova') renderNova(); else $('novaDot').hidden=novaGain()<=0; }\n\n// ---------- actions ----------\nfunction buyProducer(p){\n  const n=buyCount(p), c=costN(p,n); if(S.sd<c) return;\n  S.sd-=c; S.owned[p.id]=own(p.id)+n; tone(392,.12); skyDirty=true;\n  const rb=prodRows[p.id].b; rb.classList.remove('flash'); void rb.offsetWidth; rb.classList.add('flash');\n  checkCatalog(); renderAll();\n}\nfunction buyResearch(r){ if(S.sd<r.cost||has(r.id)) return; S.sd-=r.cost; S.res.push(r.id); resSig=''; tone(523,.15); tone(659,.18,.08); toast('Research done',r.n); renderAll(); }\nfunction checkCatalog(){\n  for(const c of CATALOG){ if(S.cat.includes(c.id)||!c.ok()) continue;\n    S.cat.push(c.id); catSig=''; toast('New in your catalog: '+c.n, c.f); tone(587,.2); tone(784,.25,.1); }\n}\nlet tab='build';\ndocument.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));\nfunction setTab(t){ tab=t; resSig=''; catSig=''; document.querySelectorAll('.tab').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===t)); ['build','res','cat','nova'].forEach(k=>$('pane-'+k).hidden=k!==t); renderAll(); }\ndocument.querySelectorAll('#buyMode button').forEach(b=>b.addEventListener('click',()=>{S.buy=b.dataset.m; syncBuy(); renderProducers();}));\nfunction syncBuy(){ document.querySelectorAll('#buyMode button').forEach(x=>x.setAttribute('aria-pressed',x.dataset.m===S.buy)); }\nlet confirmT=null;\n$('novaBtn').addEventListener('click',()=>{\n  const b=$('novaBtn'), g=novaGain(); if(g<=0) return;\n  if(!b.classList.contains('confirm')){ b.classList.add('confirm'); b.textContent=`Tap again to confirm (+${g} star seeds)`; clearTimeout(confirmT); confirmT=setTimeout(()=>{b.classList.remove('confirm');renderNova();},3500); return; }\n  clearTimeout(confirmT); b.classList.remove('confirm');\n  const keep={seeds:S.seeds+g,novas:S.novas+1,life:S.life,taps:S.taps,cat:S.cat,seen:S.seen,started:S.started,best:S.best,catches:S.catches,buy:S.buy,sound:S.sound,bright:S.bright,calm:S.calm};\n  S=Object.assign(fresh(),keep); meteor=null; resSig=''; catSig=''; skyDirty=true; novaRing=0.001; save();\n  setTab('build');\n  showModal(`<h3>A new ${star(S.novas).k.toLowerCase()} is born</h3><p>Your old star scattered its heavy elements into space. You now hold ${S.seeds} star seeds, worth +${S.seeds*10}% stardust from the first tap.</p><button class=\"big-btn\" id=\"mOk\">Start the new system</button>`);\n});\n\n// ---------- toast / modal ----------\nlet toastT=null;\nfunction toast(title,sub){ const t=$('toast'); t.innerHTML=`<b>${title}</b>${sub?`<span>${sub}</span>`:''}`; t.hidden=false; clearTimeout(toastT); toastT=setTimeout(()=>t.hidden=true,sub?4200:2200); }\nfunction showModal(html){ $('modalCard').innerHTML=html; $('modal').hidden=false; const ok=$('mOk'); if(ok) ok.onclick=()=>{$('modal').hidden=true;}; }\n\n// ---------- settings ----------\nfunction applySettings(){\n  $('dimmer').style.opacity=((100-S.bright)/100*0.85).toFixed(3);\n  $('bright').value=S.bright; $('brightVal').textContent=S.bright+'%';\n  $('setCalm').setAttribute('aria-pressed',S.calm); $('setSound').setAttribute('aria-pressed',S.sound);\n}\n$('setBtn').addEventListener('click',()=>{ renderStats(); $('settings').hidden=false; });\n$('setClose').addEventListener('click',()=>{ $('settings').hidden=true; save(); });\n$('settings').addEventListener('click',e=>{ if(e.target.id==='settings') $('settings').hidden=true; });\n$('bright').addEventListener('input',e=>{ S.bright=+e.target.value; applySettings(); });\n$('setCalm').addEventListener('click',()=>{ S.calm=!S.calm; applySettings(); });\n$('setSound').addEventListener('click',()=>{ S.sound=!S.sound; applySettings(); if(S.sound) tone(440,.15); });\n$('wipeBtn').addEventListener('click',()=>{\n  const b=$('wipeBtn');\n  if(b.dataset.c!=='1'){ b.dataset.c='1'; b.textContent='Tap again to erase everything'; setTimeout(()=>{b.dataset.c='';b.textContent='Erase save';},3500); return; }\n  try{localStorage.removeItem(KEY);}catch(e){}\n  const keep={bright:S.bright,calm:S.calm,sound:S.sound};\n  S=Object.assign(fresh(),keep); meteor=null; resSig=''; catSig=''; skyDirty=true; b.dataset.c=''; b.textContent='Erase save';\n  $('settings').hidden=true; setTab('build'); toast('Save erased','A fresh dust cloud is waiting.');\n});\nfunction renderStats(){\n  const rows=[['Time observing',fmtTime((Date.now()-S.started)/1000)],['Lifetime stardust',fmt(S.life)],['Best rate',fmt(S.best)+'/s'],['Taps',fmt(S.taps)],['Meteors caught',S.catches],['Supernovae',S.novas]];\n  $('statKv').innerHTML=rows.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('');\n}\n\n// ---------- sound: soft sine tones on a pentatonic scale ----------\nlet AC=null;\nfunction tone(f,dur,delay){\n  if(!S.sound) return;\n  try{ if(!AC) AC=new (window.AudioContext||window.webkitAudioContext)(); if(AC.state==='suspended') AC.resume();\n    const t0=AC.currentTime+(delay||0), o=AC.createOscillator(), g=AC.createGain();\n    o.type='sine'; o.frequency.setValueAtTime(f,t0); g.gain.setValueAtTime(0.0001,t0); g.gain.exponentialRampToValueAtTime(0.035,t0+0.02); g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);\n    o.connect(g); g.connect(AC.destination); o.start(t0); o.stop(t0+dur+0.05);\n  }catch(e){}\n}\nconst PENTA=[262,294,330,392,440,523,587,659];\n\n// ---------- canvas ----------\nconst sky=$('sky'), skx=sky.getContext('2d'), cv=$('sys'), ctx=cv.getContext('2d');\nlet W=0,H=0,DPR=1,cx=0,cy=0,R=30,maxR=200; const TILT=0.42;\nlet skyDirty=true, skySig='';\nfunction resize(){\n  const r=$('scene').getBoundingClientRect(); DPR=Math.min(2,window.devicePixelRatio||1); W=r.width; H=r.height;\n  for(const c of [sky,cv]){ c.width=Math.round(W*DPR); c.height=Math.round(H*DPR); }\n  ctx.setTransform(DPR,0,0,DPR,0,0); skx.setTransform(DPR,0,0,DPR,0,0);\n  cx=W/2; cy=H*0.57; R=Math.max(15,Math.min(46,W*0.07,H*0.1));\n  maxR=Math.max(R*3.2,Math.min(W*0.47-8,(H*0.39)/TILT));\n  skyDirty=true;\n}\nwindow.addEventListener('resize',resize);\ntry{ new ResizeObserver(()=>{const r=$('scene').getBoundingClientRect(); if(Math.abs(r.width-W)>0.5||Math.abs(r.height-H)>0.5) resize();}).observe($('scene')); }catch(e){}\n\nfunction rng(seed){ let a=seed>>>0; return ()=>{a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}; }\nconst bucket=n=>n<=0?0:Math.min(40,Math.floor(Math.log2(n+1)*3));\nfunction paintSky(){\n  const sig=[W,H,bucket(own('star')),bucket(own('neb')),bucket(own('gal')),bucket(own('web'))].join('|');\n  if(!skyDirty&&sig===skySig) return; skySig=sig; skyDirty=false;\n  const g=skx; g.clearRect(0,0,W,H); g.fillStyle='#0b0e18'; g.fillRect(0,0,W,H);\n  const r=rng(7+S.novas*31);\n  // nebulae: very faint coloured clouds\n  const nNeb=Math.min(6,Math.ceil(Math.log2(own('neb')+1)));\n  const nebCols=['#8f89bf','#b48693','#73a39f','#9a86b8','#a0907a'];\n  for(let i=0;i<nNeb;i++){ const x=r()*W,y=r()*H,rad=Math.max(W,H)*(0.18+r()*0.22),c=nebCols[i%nebCols.length];\n    const gr=g.createRadialGradient(x,y,0,x,y,rad); gr.addColorStop(0,rgba(c,.085)); gr.addColorStop(.6,rgba(c,.03)); gr.addColorStop(1,rgba(c,0)); g.fillStyle=gr; g.fillRect(0,0,W,H); }\n  // galaxies: small tilted spirals\n  const nGal=Math.min(10,Math.ceil(Math.log2(own('gal')+1)*1.5));\n  const gals=[];\n  for(let i=0;i<nGal;i++){ const x=r()*W,y=r()*H*0.9,s=6+r()*12,rot=r()*3.14,tilt=.35+r()*.5; gals.push([x,y]);\n    g.save(); g.translate(x,y); g.rotate(rot); g.scale(1,tilt);\n    const gr=g.createRadialGradient(0,0,0,0,0,s); gr.addColorStop(0,'rgba(190,195,215,.22)'); gr.addColorStop(1,'rgba(190,195,215,0)'); g.fillStyle=gr; g.beginPath(); g.arc(0,0,s,0,7); g.fill();\n    g.strokeStyle='rgba(170,178,205,.12)'; g.lineWidth=1.2;\n    for(let a=0;a<2;a++){ g.beginPath(); for(let t=0;t<4;t+=.15){ const rr=t*s*.32; g.lineTo(Math.cos(t+a*3.14)*rr,Math.sin(t+a*3.14)*rr);} g.stroke(); }\n    g.restore(); }\n  // superclusters: faint threads linking galaxies\n  if(own('web')>0&&gals.length>1){ g.strokeStyle='rgba(127,166,160,.07)'; g.lineWidth=1; g.beginPath(); for(let i=1;i<gals.length;i++){ g.moveTo(...gals[i-1]); g.lineTo(...gals[i]); } g.stroke(); }\n  // background stars: dim points, more with neighbor stars\n  const n=Math.round(W*H/2600)+Math.min(300,own('star')*6);\n  for(let i=0;i<n;i++){ const b=r(), x=r()*W, y=r()*H, warm=r();\n    g.fillStyle=warm<.2?`rgba(214,190,160,${.08+b*.28})`:warm<.35?`rgba(165,180,214,${.08+b*.28})`:`rgba(200,204,218,${.06+b*.26})`;\n    const z=b>.97?1.6:1; g.fillRect(x,y,z,z); }\n}\n// twinkle set (a handful of stars that breathe slowly)\nconst twinkles=[]; { const r=rng(99); for(let i=0;i<26;i++) twinkles.push({x:r(),y:r(),p:r()*6.28,s:.3+r()*.5}); }\n\n// objects with fixed random parameters\nconst prng=rng(2024);\nconst PLPH=PLANETS.map(()=>prng()*6.283);\nconst BELT=[]; for(let i=0;i<260;i++) BELT.push({a:prng()*6.283,d:prng()*2-1,s:.6+prng()*.8,z:prng()});\nconst DUST=[]; for(let i=0;i<120;i++) DUST.push({x:prng(),y:prng(),vx:(prng()-.5)*.006,vy:(prng()-.5)*.004,a:.08+prng()*.16,r:.6+prng()*1.1});\nconst COMETS=[]; for(let i=0;i<7;i++) COMETS.push({a:.5+prng()*.45,e:.62+prng()*.22,w:prng()*6.283,M:prng()*6.283,sp:.9+prng()*.5});\nconst STARRING=[]; for(let i=0;i<10;i++) STARRING.push({ph:prng()*6.283,d:.25+prng()*.6,h:prng()});\n\nconst SLOTF=[0,.1,.2,.31,.56,.71,.86,1], BELTF=.43;\nfunction slotR(i){ const r0=R*1.95; return r0+(maxR-r0)*SLOTF[i]; }\nconst proj=(a,r)=>[cx+Math.cos(a)*r, cy+Math.sin(a)*r*TILT];\nlet tAnim=0, pulse=0, novaRing=0;\nconst ripples=[], floats=[];\nlet hitPlanets=[];\nlet meteor=null, nextMeteor=25;\n\nfunction drawPlanet(P,x,y,pr,t){\n  const dx=cx-x, dy=cy-y, d=Math.hypot(dx,dy)||1, lx=dx/d, ly=dy/d;\n  if(P.ring){ ctx.save(); ctx.strokeStyle=rgba('#bfae86',.35); ctx.lineWidth=Math.max(1,pr*.28); ctx.beginPath(); ctx.ellipse(x,y,pr*2.1,pr*.62,-.22,Math.PI,2*Math.PI); ctx.stroke(); ctx.restore(); }\n  const g=ctx.createRadialGradient(x+lx*pr*.45,y+ly*pr*.45,pr*.1,x,y,pr*1.05);\n  g.addColorStop(0,mix(P.c,'#ddd6c8',.18)); g.addColorStop(.55,P.c); g.addColorStop(1,mix(P.c,'#05070c',.72));\n  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,y,pr,0,7); ctx.fill();\n  if(P.bands&&pr>5){ ctx.save(); ctx.beginPath(); ctx.arc(x,y,pr,0,7); ctx.clip(); ctx.strokeStyle=rgba(P.bands,.45); ctx.lineWidth=Math.max(1,pr*.14);\n    [-.45,-.1,.3].forEach(k=>{ctx.beginPath();ctx.moveTo(x-pr,y+k*pr);ctx.lineTo(x+pr,y+k*pr);ctx.stroke();}); ctx.restore(); }\n  if(P.land&&pr>3){ ctx.save(); ctx.beginPath(); ctx.arc(x,y,pr,0,7); ctx.clip(); ctx.fillStyle=rgba(P.land,.55); const sh=(t*.25)%(pr*4);\n    [[-.3,-.2,.35],[.4,.3,.28]].forEach(([a,b,s])=>{ctx.beginPath();ctx.arc(x+((a*pr+sh)%(pr*2.4))-pr*.6,y+b*pr,s*pr,0,7);ctx.fill();}); ctx.restore(); }\n  if(P.ring){ ctx.save(); ctx.strokeStyle=rgba('#bfae86',.5); ctx.lineWidth=Math.max(1,pr*.28); ctx.beginPath(); ctx.ellipse(x,y,pr*2.1,pr*.62,-.22,0,Math.PI); ctx.stroke(); ctx.restore(); }\n}\nfunction drawSun(t){\n  const sc=star(S.novas).c, s=R*(1+0.035*pulse);\n  const co=ctx.createRadialGradient(cx,cy,s*.8,cx,cy,s*2.6);\n  co.addColorStop(0,rgba(sc,.16)); co.addColorStop(1,rgba(sc,0)); ctx.fillStyle=co; ctx.beginPath(); ctx.arc(cx,cy,s*2.6,0,7); ctx.fill();\n  // limb darkening: real stars look dimmer at the edge\n  const g=ctx.createRadialGradient(cx-s*.15,cy-s*.15,s*.05,cx,cy,s);\n  g.addColorStop(0,mix(sc,'#e6dcc6',.3)); g.addColorStop(.7,sc); g.addColorStop(1,mix(sc,'#20140c',.45));\n  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(cx,cy,s,0,7); ctx.fill();\n  // slow-turning sunspots\n  ctx.save(); ctx.beginPath(); ctx.arc(cx,cy,s,0,7); ctx.clip(); ctx.fillStyle=rgba('#2a1c10',.18);\n  for(let i=0;i<3;i++){ const a=t*.06+i*2.1, x=cx+Math.cos(a)*s*.6, vis=Math.sin(a); if(vis<0) continue; ctx.beginPath(); ctx.ellipse(x,cy+(i-1)*s*.32,s*.09*vis+1,s*.07,0,0,7); ctx.fill(); }\n  ctx.restore();\n}\nfunction orbitArc(r,front,alpha){\n  ctx.strokeStyle=`rgba(150,160,190,${alpha})`; ctx.lineWidth=1; ctx.beginPath();\n  ctx.ellipse(cx,cy,r,r*TILT,0,front?0:Math.PI,front?Math.PI:2*Math.PI); ctx.stroke();\n}\nfunction kepler(M,e){ let E=M; for(let i=0;i<5;i++) E=E-(E-e*Math.sin(E)-M)/(1-e*Math.cos(E)); return E; }\n\nfunction frame(dt){\n  const sp=S.calm?0.45:1; tAnim+=dt*sp;\n  pulse=Math.max(0,pulse-dt*3);\n  paintSky();\n  ctx.clearRect(0,0,W,H);\n  const t=tAnim;\n  // twinkle\n  if(!S.calm) for(const s of twinkles){ const a=.05+.12*(0.5+0.5*Math.sin(t*s.s+s.p)); ctx.fillStyle=`rgba(205,208,222,${a})`; ctx.fillRect(s.x*W,s.y*H,1.4,1.4); }\n  // neighbour stars: a dim ring of companions that slowly brightens\n  const ns=Math.min(10,Math.ceil(Math.log2(own('star')+1)*2));\n  for(let i=0;i<ns;i++){ const q=STARRING[i], x=(q.d*W+t*2*(i%2?1:-1))%W, y=H*(0.08+0.84*q.h);\n    const g=ctx.createRadialGradient(x,y,0,x,y,5); g.addColorStop(0,'rgba(214,200,170,.4)'); g.addColorStop(1,'rgba(214,200,170,0)'); ctx.fillStyle=g; ctx.beginPath(); ctx.arc((x+W)%W,y,5,0,7); ctx.fill(); }\n  // dust motes\n  const nd=Math.min(DUST.length,own('dust')*3);\n  for(let i=0;i<nd;i++){ const d=DUST[i]; d.x=(d.x+d.vx*dt*sp+1)%1; d.y=(d.y+d.vy*dt*sp+1)%1; ctx.fillStyle=`rgba(190,178,158,${d.a})`; ctx.beginPath(); ctx.arc(d.x*W,d.y*H,d.r,0,7); ctx.fill(); }\n\n  // which planets exist\n  const nRock=Math.min(4,own('terra')), nGas=Math.min(4,own('giant'));\n  const live=[]; for(let i=0;i<nRock;i++) live.push(i); for(let i=0;i<nGas;i++) live.push(4+i);\n  const objs=[]; // {z, draw}\n  // orbits (back halves)\n  live.forEach(i=>orbitArc(slotR(i),false,.07));\n  // belt\n  const nb=Math.min(BELT.length,own('rock')*5), br=R*1.95+(maxR-R*1.95)*BELTF, bw=(maxR-R*1.95)*.05;\n  const beltFront=[];\n  for(let i=0;i<nb;i++){ const b=BELT[i], a=b.a+t*0.11/b.s, r=br+b.d*bw, [x,y]=proj(a,r);\n    if(Math.sin(a)>0){ beltFront.push([x,y,b.z]); continue; }\n    ctx.fillStyle=`rgba(150,142,128,${.25+.3*b.z})`; ctx.fillRect(x,y,1.3,1.3); }\n  // planets\n  const moonsN=Math.min(12,own('moon'));\n  hitPlanets=[];\n  live.forEach((i,li)=>{\n    const P=PLANETS[i], r=slotR(i), w=0.7*Math.pow(slotR(0)/r,1.5), a=PLPH[i]+t*w, [x,y]=proj(a,r);\n    const pr=Math.max(i<4?2.5:4,R*P.s*(0.85+0.3*(Math.sin(a)*.5+.5)));\n    objs.push({z:Math.sin(a),f:()=>{ drawPlanet(P,x,y,pr,t);\n      // moons around this planet\n      for(let m=li,k=0;m<moonsN;m+=live.length,k++){ if(k>2) break; const ma=t*(1.4-k*.3)+m*1.7, mr=pr+4+k*4;\n        const mx=x+Math.cos(ma)*mr, my=y+Math.sin(ma)*mr*.5; ctx.fillStyle='rgba(175,175,168,.75)'; ctx.beginPath(); ctx.arc(mx,my,Math.max(1,pr*.18),0,7); ctx.fill(); }\n    }});\n    hitPlanets.push({x,y,r:pr,P});\n  });\n  // comets\n  const nc=Math.min(COMETS.length,own('comet'));\n  for(let i=0;i<nc;i++){ const c=COMETS[i], A=maxR*c.a, M=c.M+t*0.35*c.sp/Math.pow(c.a,1.5), E=kepler(M%(6.283),c.e);\n    const px=A*(Math.cos(E)-c.e), py=A*Math.sqrt(1-c.e*c.e)*Math.sin(E);\n    const ox=px*Math.cos(c.w)-py*Math.sin(c.w), oy=px*Math.sin(c.w)+py*Math.cos(c.w);\n    const x=cx+ox, y=cy+oy*TILT, dist=Math.hypot(ox,oy)||1;\n    objs.push({z:oy/A,f:()=>{ const L=Math.min(maxR*.35,R*14/Math.max(.6,dist/R)), tx=x+ox/dist*L, ty=y+oy*TILT/dist*L;\n      const g=ctx.createLinearGradient(x,y,tx,ty); g.addColorStop(0,'rgba(140,180,186,.38)'); g.addColorStop(1,'rgba(140,180,186,0)');\n      ctx.strokeStyle=g; ctx.lineWidth=2.2; ctx.lineCap='round'; ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(tx,ty); ctx.stroke();\n      ctx.fillStyle='rgba(190,212,214,.7)'; ctx.beginPath(); ctx.arc(x,y,1.8,0,7); ctx.fill(); }});\n  }\n  objs.sort((a,b)=>a.z-b.z);\n  objs.filter(o=>o.z<0).forEach(o=>o.f());\n  drawSun(t);\n  live.forEach(i=>orbitArc(slotR(i),true,.1));\n  for(const [x,y,z] of beltFront){ ctx.fillStyle=`rgba(160,150,134,${.3+.35*z})`; ctx.fillRect(x,y,1.5,1.5); }\n  objs.filter(o=>o.z>=0).forEach(o=>o.f());\n\n  // supernova ring: slow and soft, never a flash\n  if(novaRing>0){ novaRing+=dt*.35; const k=novaRing; if(k>=1) novaRing=0; else { ctx.strokeStyle=rgba(star(S.novas).c,.25*(1-k)); ctx.lineWidth=6*(1-k)+1; ctx.beginPath(); ctx.arc(cx,cy,R+k*Math.max(W,H)*.7,0,7); ctx.stroke(); } }\n  // meteor\n  nextMeteor-=dt;\n  if(!meteor&&nextMeteor<=0){ const side=Math.random()<.5, y0=H*(.12+Math.random()*.3); meteor={x0:side?-20:W+20,y0,x1:side?W+20:-20,y1:y0+H*(.2+Math.random()*.35),t:0,dur:S.calm?11:8}; }\n  if(meteor){ meteor.t+=dt/meteor.dur; const m=meteor;\n    if(m.t>=1){ meteor=null; nextMeteor=55+Math.random()*60; }\n    else { const x=m.x0+(m.x1-m.x0)*m.t, y=m.y0+(m.y1-m.y0)*m.t, dx=m.x1-m.x0, dy=m.y1-m.y0, L=Math.hypot(dx,dy);\n      m.x=x; m.y=y; const tx=x-dx/L*60, ty=y-dy/L*60;\n      const g=ctx.createLinearGradient(x,y,tx,ty); g.addColorStop(0,'rgba(214,196,150,.55)'); g.addColorStop(1,'rgba(214,196,150,0)');\n      ctx.strokeStyle=g; ctx.lineWidth=2.5; ctx.lineCap='round'; ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(tx,ty); ctx.stroke();\n      ctx.strokeStyle='rgba(214,196,150,.18)'; ctx.lineWidth=1; ctx.beginPath(); ctx.arc(x,y,14+3*Math.sin(t*3),0,7); ctx.stroke();\n      ctx.fillStyle='rgba(222,208,172,.8)'; ctx.beginPath(); ctx.arc(x,y,2.6,0,7); ctx.fill(); } }\n  // ripples & floating numbers\n  for(let i=ripples.length-1;i>=0;i--){ const p=ripples[i]; p.k+=dt*1.6; if(p.k>=1){ripples.splice(i,1);continue;}\n    ctx.strokeStyle=`rgba(${p.c},${.22*(1-p.k)})`; ctx.lineWidth=1.5; ctx.beginPath(); ctx.arc(p.x,p.y,p.r0+p.k*p.r1,0,7); ctx.stroke(); }\n  ctx.textAlign='center'; ctx.font='500 13px \"JetBrains Mono\", ui-monospace, monospace';\n  for(let i=floats.length-1;i>=0;i--){ const f=floats[i]; f.k+=dt*.8; if(f.k>=1){floats.splice(i,1);continue;}\n    ctx.fillStyle=`rgba(${f.c},${.85*(1-f.k)})`; ctx.fillText(f.txt,f.x,f.y-(S.calm?8:28)*f.k); }\n}\n\n// ---------- input ----------\ncv.addEventListener('pointerdown',e=>{\n  const rc=cv.getBoundingClientRect(), x=e.clientX-rc.left, y=e.clientY-rc.top;\n  if(meteor&&meteor.x!=null&&Math.hypot(meteor.x-x,meteor.y-y)<38){ catchMeteor(); return; }\n  let mult=0, label='';\n  const pl=hitPlanets.find(p=>Math.hypot(p.x-x,p.y-y)<p.r+12);\n  if(pl){ mult=3; label=pl.P.n+' '; }\n  else if(Math.hypot(x-cx,(y-cy))<R*1.7+18) mult=1;\n  if(!mult){ ripples.push({x,y,r0:4,r1:14,k:0,c:'130,138,160'}); return; }\n  const v=tapValue()*mult; earn(v); S.taps++; pulse=1;\n  tone(PENTA[Math.floor(Math.random()*PENTA.length)]*(pl?1.5:1),.28);\n  ripples.push({x:pl?pl.x:cx,y:pl?pl.y:cy,r0:pl?pl.r:R,r1:pl?18:R*.9,k:0,c:pl?'140,180,176':'196,163,108'});\n  floats.push({txt:label+'+'+fmt(v),x:x+(Math.random()*14-7),y:y-10,k:0,c:pl?'150,190,186':'214,196,160'}); if(floats.length>24) floats.shift();\n  if(S.taps===1||S.taps===1000) checkCatalog();\n  renderTop();\n});\nfunction catchMeteor(){\n  const r=rate(), m=meteor; S.catches++; meteor=null; nextMeteor=55+Math.random()*60;\n  if(Math.random()<.5||r<1){ const amt=Math.max(r*90,tapValue()*60); earn(amt); floats.push({txt:'Meteor +'+fmt(amt),x:m.x,y:m.y,k:0,c:'214,196,150'}); toast('Meteor caught',`+${fmt(amt)} stardust`); }\n  else { S.boostUntil=Date.now()+20000; floats.push({txt:'Gravity surge ×5',x:m.x,y:m.y,k:0,c:'214,196,150'}); toast('Gravity surge','All stardust ×5 for 20 seconds'); }\n  ripples.push({x:m.x,y:m.y,r0:4,r1:30,k:0,c:'214,196,150'}); tone(659,.3); tone(880,.35,.1); renderAll();\n}\n\n// ---------- loop ----------\nlet lastT=performance.now(), uiAcc=0, saveAcc=0;\nfunction loop(now){\n  const dt=Math.min(0.1,(now-lastT)/1000); lastT=now;\n  const r=rate(); earn(r*dt); if(r>S.best) S.best=r;\n  frame(dt);\n  uiAcc+=dt; if(uiAcc>0.25){ uiAcc=0; checkCatalog(); renderAll(); }\n  saveAcc+=dt; if(saveAcc>5){ saveAcc=0; save(); }\n  requestAnimationFrame(loop);\n}\ndocument.addEventListener('visibilitychange',()=>{ if(document.hidden) save(); else lastT=performance.now(); });\nwindow.addEventListener('pagehide',save);\n\nfunction start(data){\n  load(data&&data.S);\n  const away=(Date.now()-S.last)/1000;\n  buildProducers(); syncBuy(); applySettings(); resize();\n  if(away>60&&rate()>0){ const secs=Math.min(away,OFFLINE_CAP), amt=rate()/boostMult()*secs*0.5; earn(amt);\n    showModal(`<h3>While you were away</h3><p>Your system kept gathering for ${fmtTime(secs)} at half speed.</p><div class=\"gain\">+${fmt(amt)} stardust</div><button class=\"big-btn\" id=\"mOk\">Collect</button>`); }\n  setTab('build'); requestAnimationFrame(t=>{lastT=t;loop(t);});\n}\nif(hot&&hot.ready) hot.ready(start); else start(hot&&hot.data?hot.data:{});\n})();\n</script>\n</body></html>";
